from common import *
def main():
    save_source(__file__)
    # Wait for the actual fit/infer/evaluate process, allowing safe recovery after failure.
    pid=int(sys.argv[1])
    while True:
        try:os.kill(pid,0)
        except ProcessLookupError:break
        time.sleep(15)
    assert all((BASE/'metrics'/f'{arm}.json').is_file() for arm in VARIANTS),'upstream stopped'
    for name in ['analysis','strategy','publish']:
        with (BASE/'docs'/f'{name}.log').open('a') as f:subprocess.run([sys.executable,'-u',str(TMP/f'{name}.py')],cwd=ROOT,stdout=f,stderr=subprocess.STDOUT,check=True)
if __name__=='__main__':main()
